"""Executes a type-checked Program over typed rows, producing ordered aggregated buckets."""
from datetime import datetime

from . import badrecords, dtypes
from .ast_nodes import Apply, Filter
from .aggregates import compute
from .errors import RuntimeFailure, TypeCheckError
from .evaluator import evaluate
from .timeutil import epoch_micros, format_utc, from_epoch_micros
from .typecheck import output_schema

_MICROS_PER_SECOND = 1_000_000


class Bucket:
    """One output record before formatting: window bounds, group key, aggregate values
    and post-aggregation calc values."""

    def __init__(self, window_start, window_end, group_key, values):
        self.window_start = window_start
        self.window_end = window_end
        self.group_key = group_key
        self.values = values
        self.calcs = {}


def run(program, records, schema_calcs=(), row_schema=None, sink=None):
    """Return the Buckets in normalized order, with post-agg calcs evaluated.

    `records` yields (Origin, row) pairs; `schema_calcs` are the using-schema's
    calculated fields in evaluation order; `row_schema` is the checked row
    typing (needed for post-agg calcs). Rows whose row-level evaluation fails
    are handed to `sink` (when given) and skipped.
    """
    rows = prepare_rows(program, schema_calcs, records, sink)
    buckets = sorted(_bucketize(program, rows), key=bucket_sort_key)
    if program.post_calcs:
        _post_aggregate(program, buckets, row_schema or {})
    return buckets


def prepare_rows(program, schema_calcs, records, sink=None):
    """Materialize calculated fields and run filter/apply statements row by row;
    returns the rows that survive the filters."""
    calcs = [(f.name, f.expr, f.type) for f in schema_calcs]
    calcs += [(c.name, c.expr, c.declared_type) for c in program.pre_calcs]
    return [row for _, row in transform_rows(records, calcs, program.row_ops, sink)]


def transform_rows(records, calcs, row_ops, sink=None):
    """Evaluate (name, expr, declared_type) calcs, then filter/apply statements, over
    (Origin, row) records; returns the surviving (Origin, row) pairs."""
    result = []
    for origin, row in records:
        try:
            out = _evaluate_row(dict(row), calcs, row_ops)
        except (RuntimeFailure, ArithmeticError, ValueError, RecursionError) as exc:
            if sink is None:
                raise
            _reject(sink, origin, badrecords.RUNTIME_ERROR, exc, RuntimeFailure, row)
            continue
        except TypeError as exc:
            if sink is None:
                raise
            _reject(sink, origin, badrecords.TYPE_ERROR, exc, TypeCheckError, row)
            continue
        if out is not None:
            result.append((origin, out))
    return result


def _evaluate_row(row, calcs, row_ops):
    """Return the transformed row, or None when a filter drops it (null counts as false)."""
    for name, expr, declared in calcs:
        row[name] = coerce(evaluate(expr, row), declared)
    for op in row_ops:
        if isinstance(op, Filter):
            if evaluate(op.predicate, row) is not True:
                return None
        elif isinstance(op, Apply):
            row[op.column] = evaluate(op.expr, row)
    return row


def _reject(sink, origin, error_type, exc, error_class, row):
    message = exc.message if isinstance(exc, RuntimeFailure) else (str(exc) or type(exc).__name__)
    if isinstance(exc, RecursionError):
        message = "expression nesting too deep"
    sink.reject(badrecords.BadRecord(origin, error_type, message,
                                     {"record": {k: _show(v) for k, v in row.items()}},
                                     error_class))


def _show(value):
    if isinstance(value, datetime):
        return format_utc(value)
    return value


def coerce(value, declared):
    """Widen int values of float-typed fields."""
    if declared == dtypes.FLOAT and isinstance(value, int) and not isinstance(value, bool):
        return float(value)
    return value


def _bucketize(program, rows):
    group_cols = program.group_columns
    window = program.window

    if not group_cols and window is None:
        return [Bucket(None, None, (), _aggregate(program, rows))]

    width = window.seconds * _MICROS_PER_SECOND if window else None
    buckets = {}
    for row in rows:
        start = None
        if width is not None:
            start = epoch_micros(row["timestamp"]) // width * width
        key = (start, tuple(row[c] for c in group_cols))
        buckets.setdefault(key, []).append(row)

    result = []
    for (start, group_key), bucket_rows in buckets.items():
        ws = we = None
        if start is not None:
            ws = from_epoch_micros(start)
            we = from_epoch_micros(start + width)
        result.append(Bucket(ws, we, group_key, _aggregate(program, bucket_rows)))
    return result


def _aggregate(program, rows):
    return {item.alias: compute(item, rows) for item in program.aggregate.items}


def bucket_sort_key(bucket):
    start = bucket.window_start
    window_part = (0,) if start is None else (1, start)
    return (window_part, tuple(_value_sort_key(v) for v in bucket.group_key))


def _value_sort_key(value):
    # Nulls sort first; within a column all non-null values share one kind.
    if value is None:
        return (0, 0)
    return (1, value)


def _post_aggregate(program, buckets, row_schema):
    """Evaluate post-agg calcs over the ordered buckets, one calc at a time."""
    types = output_schema(program, row_schema)
    frame_rows = []
    for bucket in buckets:
        row = {}
        if program.window is not None:
            row["window_start"] = bucket.window_start
            row["window_end"] = bucket.window_end
        row.update(zip(program.group_columns, bucket.group_key))
        row.update(bucket.values)
        frame_rows.append({name: coerce(value, types[name]) for name, value in row.items()})

    for calc in program.post_calcs:
        values = [coerce(evaluate(calc.expr, row, (frame_rows, idx)), calc.declared_type)
                  for idx, row in enumerate(frame_rows)]
        for row, bucket, value in zip(frame_rows, buckets, values):
            row[calc.name] = value
            bucket.calcs[calc.name] = value
"""Normalization (row ordering, key ordering) and deterministic JSON serialization."""
import json
import math
from datetime import datetime

from .errors import RuntimeFailure
from .timeutil import format_utc


def build_document(program, buckets):
    """Produce the JSON-ready value from normalized-order buckets.

    Keys: window bounds, group keys, aggregate aliases (sorted), then
    post-aggregation calcs (sorted).
    """
    aliases = sorted(item.alias for item in program.aggregate.items)
    calc_names = sorted(calc.name for calc in program.post_calcs)
    group_cols = program.group_columns
    windowed = program.window is not None

    if not group_cols and not windowed:
        bucket = buckets[0]
        record = {alias: _json_value(bucket.values[alias]) for alias in aliases}
        for name in calc_names:
            record[name] = _json_value(bucket.calcs[name])
        return record

    records = []
    for bucket in buckets:
        record = {}
        if windowed:
            record["window_start"] = format_utc(bucket.window_start)
            record["window_end"] = format_utc(bucket.window_end)
        for col, value in zip(group_cols, bucket.group_key):
            record[col] = _json_value(value)
        for alias in aliases:
            record[alias] = _json_value(bucket.values[alias])
        for name in calc_names:
            record[name] = _json_value(bucket.calcs[name])
        records.append(record)
    return records


def _json_value(value):
    if isinstance(value, datetime):
        return format_utc(value)
    if isinstance(value, float) and not math.isfinite(value):
        raise RuntimeFailure("result contains a non-finite number")
    return value


def serialize(document):
    return json.dumps(document, indent=2, ensure_ascii=False, allow_nan=False) + "\n"
"""Rejected-row bookkeeping: classification, strict-mode termination and JSONL output."""
import json

from .errors import IOFailure, RuntimeFailure, TypeCheckError

PARSE_TYPE_MISMATCH = "PARSE_TYPE_MISMATCH"
TIMESTAMP_PARSE_ERROR = "TIMESTAMP_PARSE_ERROR"
RUNTIME_ERROR = "RUNTIME_ERROR"
TYPE_ERROR = "TYPE_ERROR"
MISSING_REQUIRED_FIELD = "MISSING_REQUIRED_FIELD"
PARQUET_TYPE_MISMATCH = "PARQUET_TYPE_MISMATCH"


class Origin:
    """Where a row came from: file path, 1-based line (text files) or row index (Parquet)."""

    def __init__(self, path, line=None, row_index=None):
        self.path = path
        self.line = line
        self.row_index = row_index

    def describe(self):
        if self.line is not None:
            return f"{self.path}:{self.line}"
        return f"{self.path} row {self.row_index}"

    def sort_key(self):
        return (self.path, self.line if self.line is not None else -1,
                self.row_index if self.row_index is not None else -1)


class BadRecord:
    def __init__(self, origin, error_type, message, context=None, error_class=None):
        self.origin = origin
        self.error_type = error_type
        self.message = message
        self.context = context or {}
        # The MTLError subclass raised for this record in strict mode.
        self.error_class = error_class or _DEFAULT_ERRORS[error_type]

    def to_json(self):
        return {
            "file": self.origin.path,
            "line": self.origin.line,
            "row_index": self.origin.row_index,
            "error_type": self.error_type,
            "error": self.error_type,
            "message": self.message,
            "context": self.context,
        }


_DEFAULT_ERRORS = {
    PARSE_TYPE_MISMATCH: TypeCheckError,
    TIMESTAMP_PARSE_ERROR: TypeCheckError,
    TYPE_ERROR: TypeCheckError,
    MISSING_REQUIRED_FIELD: TypeCheckError,
    PARQUET_TYPE_MISMATCH: TypeCheckError,
    RUNTIME_ERROR: RuntimeFailure,
}


class BadRecordSink:
    """Collects rejected rows; in strict mode the first one aborts the run."""

    def __init__(self, strict):
        self.strict = strict
        self.records = []

    def reject(self, record):
        self.records.append(record)
        if self.strict:
            raise record.error_class(f"{record.origin.describe()}: {record.error_type}: "
                                     f"{record.message}")

    def write(self, path):
        """Write the rejected rows as JSON Lines, sorted by file then line; no rows, no file."""
        if not path or not self.records:
            return
        ordered = sorted(self.records, key=lambda r: r.origin.sort_key())
        lines = [json.dumps(_sanitize(r.to_json()), ensure_ascii=False, allow_nan=False)
                 for r in ordered]
        try:
            with open(path, "w", encoding="utf-8", newline="\n") as fh:
                fh.write("\n".join(lines) + "\n")
        except OSError as exc:
            raise IOFailure(f"cannot write bad records '{path}': {exc}") from exc


def _sanitize(value):
    """Make a value JSON-safe: undecodable bytes become U+FFFD, non-JSON types become text."""
    if isinstance(value, dict):
        return {str(k): _sanitize(v) for k, v in value.items()}
    if isinstance(value, (list, tuple)):
        return [_sanitize(v) for v in value]
    if isinstance(value, str):
        return value.encode("utf-8", "surrogateescape").decode("utf-8", "replace")
    if isinstance(value, float) and value != value:
        return "NaN"
    if isinstance(value, float) and value in (float("inf"), float("-inf")):
        return "Infinity" if value > 0 else "-Infinity"
    if value is None or isinstance(value, (bool, int, float)):
        return value
    return str(value)
"""Pipeline parameters: merging DSL defaults with --param values into typed constants."""
from . import dtypes
from .errors import DSLSyntaxError, IOFailure, TypeCheckError


class ParamValue:
    def __init__(self, name, param_type, value):
        self.name = name
        self.type = param_type
        self.value = value


def parse_cli_params(items):
    """Turn ['key=value', ...] into a dict; the last duplicate wins."""
    values = {}
    for item in items:
        key, sep, value = item.partition("=")
        key = key.strip()
        if not sep or not key:
            raise IOFailure(f"invalid --param '{item}': expected key=value")
        values[key] = value
    return values


def check_provided(decls, cli_values, strict=False):
    """DSL errors: parameters without a default that were not supplied (and, in
    strict mode, supplied parameters the pipeline does not declare)."""
    missing = [d.name for d in decls if d.default is None and d.name not in cli_values]
    if missing:
        raise DSLSyntaxError(f"missing value for parameter(s) without default: "
                             f"{', '.join(missing)}")
    if strict:
        declared = {d.name for d in decls}
        unknown = sorted(k for k in cli_values if k not in declared)
        if unknown:
            raise DSLSyntaxError(f"undeclared parameter(s) supplied: {', '.join(unknown)}")


def resolve(decls, cli_values, ts_parser):
    """Return name -> ParamValue; values that do not fit their type are type errors."""
    resolved = {}
    for decl in decls:
        param_type = decl.type
        if param_type is None:
            param_type = decl.default.type if decl.default is not None else dtypes.STRING
        default = None
        if decl.default is not None:
            default = _from_literal(decl, param_type, ts_parser)
        if decl.name in cli_values:
            value = _from_text(decl.name, param_type, cli_values[decl.name], ts_parser)
        else:
            value = default
        resolved[decl.name] = ParamValue(decl.name, param_type, value)
    return resolved


def _from_literal(decl, param_type, ts_parser):
    lit = decl.default
    if lit.type == param_type:
        return lit.value
    if param_type == dtypes.FLOAT and lit.type == dtypes.INT:
        return float(lit.value)
    if param_type == dtypes.TIMESTAMP and lit.type == dtypes.STRING:
        try:
            return ts_parser.parse(lit.value)
        except ValueError as exc:
            raise TypeCheckError(f"line {decl.line}: default of parameter '{decl.name}' is not "
                                 f"a valid timestamp: {exc}") from exc
    raise TypeCheckError(f"line {decl.line}: default of parameter '{decl.name}' has type "
                         f"{lit.type}, expected {param_type}")


def _from_text(name, param_type, text, ts_parser):
    if param_type == dtypes.STRING:
        return text
    try:
        if param_type == dtypes.TIMESTAMP:
            return ts_parser.parse(text)
        return dtypes.parse_text(text.strip(), param_type)
    except ValueError as exc:
        raise TypeCheckError(f"--param {name}={text!r} is not a valid {param_type}: "
                             f"{exc}") from exc
"""Timestamp parsing, timezone handling, epoch arithmetic and UTC formatting."""
from datetime import datetime, timedelta, timezone
from zoneinfo import ZoneInfo, ZoneInfoNotFoundError

EPOCH = datetime(1970, 1, 1, tzinfo=timezone.utc)
ONE_MICROSECOND = timedelta(microseconds=1)


def resolve_timezone(name):
    """Return a tzinfo for an IANA name; raise ValueError when unknown."""
    if name in ("UTC", "Z", "utc"):
        return timezone.utc
    try:
        return ZoneInfo(name)
    except (ZoneInfoNotFoundError, ValueError, OSError) as exc:
        raise ValueError(f"unknown timezone '{name}'") from exc


class TimestampParser:
    """Parses raw timestamp strings into timezone-aware UTC datetimes."""

    def __init__(self, default_tz, fmt=None):
        self.default_tz = default_tz
        self.fmt = fmt

    def parse(self, text):
        """Parse text; raise ValueError when it is not a valid timestamp."""
        raw = text.strip()
        if not raw:
            raise ValueError("empty timestamp")
        if self.fmt is not None:
            dt = datetime.strptime(raw, self.fmt)
        else:
            dt = _parse_iso(raw)
        if dt.tzinfo is None or dt.tzinfo.utcoffset(dt) is None:
            dt = dt.replace(tzinfo=self.default_tz)
        return dt.astimezone(timezone.utc)


def _parse_iso(raw):
    candidate = raw
    if candidate[-1] in "zZ":
        candidate = candidate[:-1] + "+00:00"
    return datetime.fromisoformat(candidate)


def epoch_micros(dt):
    return (dt - EPOCH) // ONE_MICROSECOND


def from_epoch_micros(micros):
    return EPOCH + timedelta(microseconds=micros)


def format_utc(dt):
    """ISO 8601 in UTC with a trailing Z."""
    dt = dt.astimezone(timezone.utc)
    if dt.microsecond:
        return dt.strftime("%Y-%m-%dT%H:%M:%S.%f") + "Z"
    return dt.strftime("%Y-%m-%dT%H:%M:%S") + "Z"
